#include <iostream>
using namespace std;

int sumTo(int n) {
    int total = 0;
    for (int i = 1; i <= n; i++) {
        total = total + i;
    }
    return total;
}

int main() {
    cout << sumTo(4) << endl;
    cout << sumTo(5) << endl;
    return 0;
}

